-- =====================================================================
-- GesCaisse : société de démonstration « Laverie » — SQL Server (version .NET)
-- Société « Laverie Éclat Blanc » avec sa caisse LAV1 de type Laverie, son dépôt, ses modes de paiement,
-- 6 catégories et 24 articles avec leur image (20 prestations sans suivi de stock et 4 produits
-- en stock), 4 tiers (entreprises et particuliers, dont 2 clients en compte) et 20 ventes à ces
-- tiers (5 chacun, dont 7 par compte, et 2 règlements) sur les 5 jours précédant l'exécution,
-- en journées clôturées, 3 dépôts de linge, 5 produits d'entretien consommables (non vendus en caisse),
-- 2 achats au fournisseur (un réglé par carte, un à crédit) et une consommation, dans le dépôt des achats.
-- Mode « Compte client » créé. La société de démonstration existante
-- n'est pas modifiée.
--
-- À exécuter sur la base LOCALE de test (jamais en production), après avoir lancé une fois l'application.
-- Le script peut être relancé : ce qui existe déjà (société de code LAVERIE, comptes, articles…) est conservé.
-- Comptes (mot de passe 123, à changer) : laverie (administrateur), laverie.caisse (caissière).
-- Pour vendre : Caisses > LAV1 > ouvrir une journée, puis Vendre.
-- Généré par Scripts/images_demo/generer_demo_laverie.py.
-- =====================================================================

SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @t INT, @admin INT, @caissier INT, @dep INT, @tva INT, @c INT;
DECLARE @caisse INT, @code NVARCHAR(50), @motif INT, @motifRegl INT, @ventes INT, @j INT, @cmd INT, @l INT, @op INT, @esp INT, @mm INT, @cb INT, @cpt INT;
DECLARE @depots INT, @num INT, @jd INT, @motifAcompte INT;
DECLARE @achats INT, @numA INT, @fourn INT, @achat INT, @ach INT;
BEGIN TRANSACTION;

-- Société (code LAVERIE)
INSERT INTO Tenants (Nom, Code, Actif, ModeAcces, DateCreation, PosVenteSansStock, ModulePointVente, Adresse, Ville, Pays, Email, Telephone)
    SELECT N'Laverie Éclat Blanc', N'LAVERIE', 1, N'Licence', GETDATE(), 1, 1, N'Avenue de la Laverie, BP 4321', N'Libreville', N'Gabon', N'contact@laverie.demo', N'+241 01 98 76 54'
    WHERE NOT EXISTS (SELECT 1 FROM Tenants WHERE Code = 'LAVERIE');
SET @t = (SELECT MIN(Id) FROM Tenants WHERE Code = 'LAVERIE');

-- Comptes : administrateur et caissière (mot de passe 123)
INSERT INTO Utilisateurs (NomUtilisateur, MotPasse, NomComplet, Profil, PeutValiderOperations, TenantId)
    SELECT N'laverie', N'pmWkWSBCL51Bfkhn79xPuKBKHz//H6B+mY6G9/eieuM=', N'Gérant de la laverie', N'Admin', 1, @t WHERE NOT EXISTS (SELECT 1 FROM Utilisateurs WHERE NomUtilisateur = N'laverie');
INSERT INTO Utilisateurs (NomUtilisateur, MotPasse, NomComplet, Profil, PeutValiderOperations, TenantId)
    SELECT N'laverie.caisse', N'pmWkWSBCL51Bfkhn79xPuKBKHz//H6B+mY6G9/eieuM=', N'Caissière de la laverie', N'Caissier', 1, @t WHERE NOT EXISTS (SELECT 1 FROM Utilisateurs WHERE NomUtilisateur = N'laverie.caisse');
SET @admin = (SELECT MIN(Id) FROM Utilisateurs WHERE TenantId = @t AND Profil = 'Admin');
SET @caissier = (SELECT MIN(Id) FROM Utilisateurs WHERE TenantId = @t AND Profil = 'Caissier');

